package dev.elpsy.ticket;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.elpsy.ticket.admission.*;
import dev.elpsy.ticket.catalog.*;
import dev.elpsy.ticket.catalog.Models.*;
import dev.elpsy.ticket.common.ApiErrors.Problem;
import dev.elpsy.ticket.customer.CustomerService;
import dev.elpsy.ticket.customer.CustomerService.Principal;
import dev.elpsy.ticket.inventory.*;
import dev.elpsy.ticket.inventory.RedisTicketLedger.*;
import dev.elpsy.ticket.inventory.StockHoldService.Intent;
import dev.elpsy.ticket.orders.*;
import dev.elpsy.ticket.orders.OrderModels.*;
import dev.elpsy.ticket.orders.PurchaseModels.Purchase;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockPurchaseIntegrationTest {
 @Autowired StockHoldService holds;@Autowired StockSettlementService settlement;@Autowired StockProjectionService projections;@Autowired PurchaseService purchases;@Autowired OrderService orders;@Autowired CustomerService customers;@Autowired CatalogService catalog;
 @Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;@Autowired ObjectMapper json;@Autowired AdmissionSettings settings;@Autowired AdmissionService admission;@Autowired PlatformTransactionManager transactions;
 RedisTicketLedger ledger;Set<String> keys=new HashSet<>();String manager="bridge-"+UUID.randomUUID();
 record Fixture(Principal owner,UUID ticket,Place body,Intent intent) {}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));ledger=RedisTicketLedger.epochs(redis,json,settings.namespace());db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"unused synthetic hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(keys);keys.clear();}
 Principal customer(){var c=customers.register("sp-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());return customers.authenticate(c.token()).orElseThrow();}
 Fixture fixture(){return fixture(7200);}
 Fixture fixture(int seconds){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"bridge-"+UUID.randomUUID(),"合成演出","不售票","隔離"));var now=OffsetDateTime.now();var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成",now.plusDays(2),now.minusHours(1),now.plusSeconds(seconds)));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般",1200,4,4));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);ready(t.id());var p=customer();var b=new Place(UUID.randomUUID(),t.id(),1,1,1200);var i=holds.prepare(p,b);assertEquals("HELD",holds.apply(i.id()).state());return new Fixture(p,t.id(),b,i);}
 void ready(UUID t){var c=projections.begin(t,UUID.randomUUID(),projections.inspect(t).sourceRevision());keys.add(ledger.key(t,c.generation()));assertEquals("READY",projections.complete(c.requestId()).state());}
 Purchase accept(Fixture f){return purchases.acceptHold(f.owner(),f.intent().id());}
 UUID event(Purchase p){return db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());}
 Purchase reserve(Fixture f){var p=accept(f);assertTrue(purchases.process(event(p)));return purchases.detail(f.owner(),p.id());}
 Claim claim(Fixture f){var i=f.intent();return new Claim(i.generation(),i.id(),i.owner(),i.quantity(),i.deadlineAt().toInstant().toEpochMilli(),db.queryForObject("SELECT claim_fingerprint FROM stock_hold_intent WHERE id=?",String.class,i.id()));}
 String decision(Fixture f){return db.queryForObject("SELECT target FROM stock_hold_decision WHERE intent_id=?",String.class,f.intent().id());}
 int held(Fixture f){return db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,f.ticket());}
 void problem(String code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).code);}
 void active(Fixture f){problem("ACTIVE_STOCK_INTENTS",()->projections.begin(f.ticket(),UUID.randomUUID(),projections.inspect(f.ticket()).sourceRevision()));}

 @Test void acceptanceLinksOriginalIdentityAndDeadlineWithExactlyOneOutbox(){var f=fixture();var p=accept(f);assertEquals(f.body().requestId(),p.requestId());assertEquals(f.intent().deadlineAt().toInstant(),p.deadlineAt().toInstant());assertEquals("PROCESSING",p.status());assertEquals(0,held(f));assertEquals(1,db.queryForObject("SELECT count(*) FROM purchase_outbox WHERE purchase_id=?",Integer.class,p.id()));assertEquals(p.id(),db.queryForObject("SELECT purchase_id FROM stock_hold_acceptance WHERE intent_id=?",UUID.class,f.intent().id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_decision WHERE intent_id=?",Integer.class,f.intent().id()));active(f);}
 @Test void sixConcurrentAcceptRetriesKeepOneLinkAndOriginalDeadline()throws Exception{var f=fixture();try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<Purchase>>();for(int i=0;i<6;i++)jobs.add(()->accept(f));var r=pool.invokeAll(jobs);var p=r.getFirst().get();for(var x:r)assertEquals(p,x.get());}assertEquals(1,db.queryForObject("SELECT count(*) FROM purchase_request WHERE customer_id=?",Integer.class,f.owner().id()));assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().entries());}
 @Test void committedAcceptanceReplaysThroughLegacyUuidWithoutRedisAndWithFeatureOff(){var f=fixture();var p=accept(f);redis.delete(ledger.key(f.ticket(),1));assertEquals(p,accept(f));assertEquals(p,purchases.submit(f.owner(),f.body()));var off=new PurchaseService(db,orders,admission,false,false,60);assertEquals(p,new TransactionTemplate(transactions).execute(tx->off.acceptHold(f.owner(),f.intent().id())));}
 @Test void outsiderAndPreparedOrAbandonedIntentCannotBeAccepted(){var f=fixture();problem("NOT_FOUND",()->purchases.acceptHold(customer(),f.intent().id()));var b=new Place(UUID.randomUUID(),f.ticket(),1,1,1200);var i=holds.prepare(f.owner(),b);problem("STOCK_HOLD_NOT_READY",()->purchases.acceptHold(f.owner(),i.id()));holds.abandon(i.id());problem("STOCK_HOLD_NOT_READY",()->purchases.acceptHold(f.owner(),i.id()));}
 @Test void freshAcceptanceRequiresOriginalValidSession(){var f=fixture();db.update("UPDATE customer_account SET session_version=session_version+1 WHERE id=?",f.owner().id());problem("UNAUTHENTICATED",()->accept(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_acceptance WHERE intent_id=?",Integer.class,f.intent().id()));}
 @Test void missingOrReleasedReceiptCannotCreateAcceptance(){var f=fixture();ledger.release(f.ticket(),claim(f));problem("STOCK_HOLD_UNKNOWN",()->accept(f));redis.delete(ledger.key(f.ticket(),1));problem("STOCK_HOLD_UNKNOWN",()->accept(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM purchase_request WHERE customer_id=?",Integer.class,f.owner().id()));}
 @Test void pgStockChangeBeforeAcceptanceRefusesStaleGate(){var f=fixture();orders.place(customer(),new Place(UUID.randomUUID(),f.ticket(),1,1,1200));problem("STOCK_GATE_CLOSED",()->accept(f));assertEquals(1,held(f));assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());}
 @Test void linkFailureRollsBackRequestCommandOutboxButPreservesHeldIntent(){var f=fixture();db.execute("ALTER TABLE stock_hold_acceptance ADD CONSTRAINT bridge_link_fault CHECK(intent_id<>'"+f.intent().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->accept(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM purchase_request WHERE customer_id=?",Integer.class,f.owner().id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM purchase_command WHERE customer_id=?",Integer.class,f.owner().id()));assertEquals("HELD",holds.inspect(f.intent().id()).state());assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());}finally{db.execute("ALTER TABLE stock_hold_acceptance DROP CONSTRAINT bridge_link_fault");}assertEquals("PROCESSING",accept(f).status());}
 @Test void sharedWorkerCreatesFormalHoldAndDurableCommitWithoutResolvingRedis(){var f=fixture();var p=reserve(f);assertEquals("RESERVED",p.status());assertEquals(1,held(f));assertEquals("COMMIT",decision(f));assertEquals(p.orderId(),db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,f.intent().id()));assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,f.intent().id()));active(f);assertFalse(purchases.process(event(p)));}
 @Test void durableDecisionFailureRollsBackOrderStockAuditAndPurchaseResult(){var f=fixture();var p=accept(f);db.execute("ALTER TABLE stock_hold_decision ADD CONSTRAINT bridge_decision_fault CHECK(intent_id<>'"+f.intent().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->purchases.process(event(p)));assertEquals("PROCESSING",purchases.detail(f.owner(),p.id()).status());assertEquals(0,held(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_order WHERE customer_id=?",Integer.class,f.owner().id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM order_inventory_event WHERE ticket_id=?",Integer.class,f.ticket()));assertEquals("READY",projections.inspect(f.ticket()).state());}finally{db.execute("ALTER TABLE stock_hold_decision DROP CONSTRAINT bridge_decision_fault");}assertTrue(purchases.process(event(p)));assertEquals("COMMIT",decision(f));}
 @Test void commitReconciliationUsesFormalProofAndAllowsFreshPgSnapshot(){var f=fixture();reserve(f);assertEquals("COMMITTED",settlement.reconcile(f.intent().id()).resolution());assertEquals(Status.COMMITTED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(3,ledger.snapshot(f.ticket(),1).snapshot().available());ready(f.ticket());assertEquals(3,ledger.snapshot(f.ticket(),2).snapshot().available());assertEquals("ACKNOWLEDGED",settlement.reconcile(f.intent().id()).state());assertEquals("READY",projections.inspect(f.ticket()).state());assertEquals("ACCEPTED",holds.apply(f.intent().id()).failure());}
 @Test void cancellationCommitsReleaseDecisionBeforeLuaAndLateWorkerCannotReserve(){var f=fixture();var p=accept(f);var closed=purchases.cancel(f.owner(),p.id(),new Cancel(UUID.randomUUID(),1));assertEquals("CANCELLED",closed.status());assertEquals("RELEASE",decision(f));assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertFalse(purchases.process(event(p)));assertEquals("RELEASED",settlement.reconcile(f.intent().id()).resolution());assertEquals(4,ledger.snapshot(f.ticket(),1).snapshot().available());assertEquals(0,held(f));}
 @Test void expiryHasOriginalDeadlineAndNeedsExplicitReleaseDecision()throws Exception{var f=fixture(3);var p=accept(f);while(OffsetDateTime.now().isBefore(p.deadlineAt()))Thread.sleep(20);assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertTrue(purchases.expire(p.id()));assertEquals("EXPIRED",purchases.detail(f.owner(),p.id()).status());assertEquals("RELEASE",decision(f));assertEquals("RELEASED",settlement.reconcile(f.intent().id()).resolution());assertFalse(purchases.process(event(p)));}
 @Test void workerRejectionLeavesFormalStockUntouchedAndRecordsRelease(){var f=fixture();var p=accept(f);db.update("UPDATE customer_account SET enabled=false WHERE id=?",f.owner().id());assertTrue(purchases.process(event(p)));assertEquals("RELEASE",decision(f));assertEquals("REJECTED",db.queryForObject("SELECT status FROM purchase_request WHERE id=?",String.class,p.id()));assertEquals("RELEASED",settlement.reconcile(f.intent().id()).resolution());assertEquals(0,held(f));}
 @Test void workerStillChecksPgCapacityAfterRedisAcceptance(){var f=fixture();var p=accept(f);orders.place(customer(),new Place(UUID.randomUUID(),f.ticket(),4,1,4800));assertTrue(purchases.process(event(p)));assertEquals("REJECTED",purchases.detail(f.owner(),p.id()).status());assertEquals("SOLD_OUT",purchases.detail(f.owner(),p.id()).reason());assertEquals("RELEASE",decision(f));settlement.reconcile(f.intent().id());ready(f.ticket());assertEquals(0,ledger.snapshot(f.ticket(),2).snapshot().available());}
 @Test void redisReceiptLossAfterAcceptanceDoesNotPreventAuthoritativePgWorker(){var f=fixture();var p=accept(f);redis.delete(ledger.key(f.ticket(),1));assertTrue(purchases.process(event(p)));assertEquals("COMMIT",decision(f));assertEquals("KEY_MISSING",settlement.reconcile(f.intent().id()).resolution());assertFalse(redis.hasKey(ledger.key(f.ticket(),1)));ready(f.ticket());assertEquals(3,ledger.snapshot(f.ticket(),2).snapshot().available());}
 @Test void acceptedIntentCannotUseUnusedAbandonment(){var f=fixture();accept(f);problem("PG_COMMAND_CONFLICT",()->holds.abandon(f.intent().id()));assertEquals("ACCEPTED",holds.apply(f.intent().id()).failure());assertEquals("READY",projections.inspect(f.ticket()).state());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_hold_progress SET state='ABORTING',abort_at=clock_timestamp(),abort_reason='UNUSED_INTENT_ABANDONED' WHERE intent_id=?",f.intent().id()));}
 @Test void commitSuccessThenPgAckRollbackKeepsDecisionAndDoesNotCommitTwice(){var f=fixture();reserve(f);db.execute("ALTER TABLE stock_hold_ack ADD CONSTRAINT bridge_ack_fault CHECK(intent_id<>'"+f.intent().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->settlement.reconcile(f.intent().id()));assertEquals(Status.COMMITTED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,f.intent().id()));assertEquals("COMMIT",decision(f));assertEquals("DIRTY",projections.inspect(f.ticket()).state());active(f);}finally{db.execute("ALTER TABLE stock_hold_ack DROP CONSTRAINT bridge_ack_fault");}settlement.reconcile(f.intent().id());assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().committed());assertEquals(3,ledger.snapshot(f.ticket(),1).snapshot().available());}
 @Test void releaseSuccessThenPgAckRollbackDoesNotReturnStockTwice(){var f=fixture();var p=accept(f);purchases.cancel(f.owner(),p.id(),new Cancel(UUID.randomUUID(),1));db.execute("ALTER TABLE stock_hold_ack ADD CONSTRAINT bridge_release_ack_fault CHECK(intent_id<>'"+f.intent().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->settlement.reconcile(f.intent().id()));assertEquals(Status.RELEASED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals("DIRTY",projections.inspect(f.ticket()).state());}finally{db.execute("ALTER TABLE stock_hold_ack DROP CONSTRAINT bridge_release_ack_fault");}settlement.reconcile(f.intent().id());assertEquals(4,ledger.snapshot(f.ticket(),1).snapshot().available());}
 @Test void oppositeRedisTerminalResultIsNotReversed(){var f=fixture();reserve(f);ledger.release(f.ticket(),claim(f));assertEquals("REDIS_DECISION_CONFLICT",settlement.reconcile(f.intent().id()).failure());active(f);assertEquals(Status.RELEASED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(1,held(f));}
 @Test void corruptionDoesNotAcknowledgeOrOverwriteLedger(){var f=fixture();reserve(f);redis.delete(ledger.key(f.ticket(),1));redis.opsForValue().set(ledger.key(f.ticket(),1),"synthetic corruption");assertEquals("REDIS_CORRUPT",settlement.reconcile(f.intent().id()).failure());active(f);assertEquals("synthetic corruption",redis.opsForValue().get(ledger.key(f.ticket(),1)));}
 @Test void concurrentWorkerDuplicatesAndSettlementRetriesCreateOneOrderAndAck()throws Exception{var f=fixture();var p=accept(f);try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<Boolean>>();for(int i=0;i<6;i++)jobs.add(()->purchases.process(event(p)));int changed=0;for(var r:pool.invokeAll(jobs))if(r.get())changed++;assertEquals(1,changed);var retry=new ArrayList<Callable<StockSettlementService.Outcome>>();for(int i=0;i<6;i++)retry.add(()->settlement.reconcile(f.intent().id()));for(var r:pool.invokeAll(retry))assertEquals("ACKNOWLEDGED",r.get().state());}assertEquals(1,held(f));assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,f.intent().id()));}
 @Test void cancellationAndWorkerRaceProduceOneIrreversibleDecision()throws Exception{var f=fixture();var p=accept(f);try(var pool=Executors.newFixedThreadPool(2)){var tasks=List.<Callable<String>>of(()->{purchases.process(event(p));return "WORKER";},()->{try{return purchases.cancel(f.owner(),p.id(),new Cancel(UUID.randomUUID(),1)).status();}catch(Problem e){assertTrue(Set.of("STALE_VERSION","ORDER_CREATED").contains(e.code));return e.code;}});for(var r:pool.invokeAll(tasks))assertNotNull(r.get());}var result=purchases.detail(f.owner(),p.id());assertTrue(Set.of("RESERVED","CANCELLED").contains(result.status()));assertEquals(result.status().equals("RESERVED")?"COMMIT":"RELEASE",decision(f));assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_hold_decision WHERE intent_id=?",Integer.class,f.intent().id()));settlement.reconcile(f.intent().id());}
 @Test void formalOrderCancellationBeforeRedisCommitDoesNotFlipOriginalDecision(){var f=fixture();var p=reserve(f);orders.cancel(f.owner(),p.orderId(),new Cancel(UUID.randomUUID(),1));assertEquals(0,held(f));assertEquals("COMMIT",decision(f));assertEquals("COMMITTED",settlement.reconcile(f.intent().id()).resolution());ready(f.ticket());assertEquals(4,ledger.snapshot(f.ticket(),2).snapshot().available());}
 @Test void acceptanceDecisionAndAckEvidenceCannotBeEditedOrDeleted(){var f=fixture();var p=reserve(f);settlement.reconcile(f.intent().id());for(var table:List.of("stock_hold_acceptance","stock_hold_decision","stock_hold_ack")){assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM "+table+" WHERE intent_id=?",f.intent().id()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE "+table+" SET created_at=created_at WHERE intent_id=?",f.intent().id()));}assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE purchase_request SET quantity=2,total_twd=2400 WHERE id=?",p.id()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE purchase_request SET status='PROCESSING',version=1,order_id=NULL,closed_at=NULL WHERE id=?",p.id()));}
 @Test void noDecisionOrUncommittedOuterTransactionCannotRunSettlement(){var f=fixture();accept(f);problem("STOCK_DECISION_NOT_READY",()->settlement.reconcile(f.intent().id()));new TransactionTemplate(transactions).execute(tx->{assertThrows(IllegalStateException.class,()->settlement.reconcile(f.intent().id()));return null;});assertEquals(Phase.OPEN,ledger.snapshot(f.ticket(),1).snapshot().phase());}
}
